#include <stdio.h>
#include <cstring>

int main() {
    int suu;
    const int MAX_V = 10000;
    bool prime[MAX_V + 1] = {0}; // Initialize array with zeros

    for (int i = 2; i * i <= MAX_V; i++) {
        if (!prime[i]) {
            for (int k = i * i; k <= MAX_V; k += i) {
                prime[k] = true; // Mark non-prime
            }
        }
    }

    while (scanf("%d", &suu) == 1 && suu != 0) { // Combined input and exit check
        int an1 = -1, an2 = -1;
        for (int k = suu; k >= 2; k--) { // Check backwards for efficiency
            if (!prime[k - 2] && !prime[k]) {
                an1 = k - 2;
                an2 = k;
                printf("%d %d\n", an1, an2);
                break;
            }
        }
    }
    return 0;
}

